export function nodeById(nodes,id){return nodes.find(n=>n.id===id)||null;}
export function ancestors(nodes,id){const result=[],seen=new Set();let current=nodeById(nodes,id);while(current){if(seen.has(current.id))throw new Error('Cyclic model hierarchy');seen.add(current.id);result.unshift(current);current=current.parent?nodeById(nodes,current.parent):null;}return result;}
export function worldPosition(nodes,id,exploded=false){const chain=ancestors(nodes,id);if(!chain.length)throw new Error('Unknown component '+id);return chain.reduce((p,n,i)=>p.map((v,k)=>v+n.position[k]+(exploded&&k===1&&i>0?(n.minor?.65:.85):0)),[0,0,0]);}
export function searchWorld(nodes,query){const q=query.trim().toLowerCase();return nodes.filter(n=>[n.label,n.id,n.purpose,n.notes,n.input,n.output].join(' ').toLowerCase().includes(q));}
export function detailVisible(node,distance,selected,allDetails=false){return !node.minor||allDetails||node.id===selected||distance<7;}
export function canStepWorld(flow,index,failureKey,failures){const failure=failures[failureKey];return index<flow.steps.length-1&&!(failure&&flow.id===failure.flow&&index>=failure.blockedStep);}
export function clampPolar(value){return Math.max(.08,Math.min(Math.PI-.08,value));}
export function validateWorld(nodes,flows,failures){const ids=new Set(nodes.map(n=>n.id));if(ids.size!==nodes.length)throw new Error('Duplicate component id');for(const n of nodes){if(n.parent&&!ids.has(n.parent))throw new Error('Unknown parent');if(n.position.length!==3||n.size.length!==3||![...n.position,...n.size].every(Number.isFinite)||n.size.some(s=>s<=0))throw new Error('Invalid component geometry');ancestors(nodes,n.id);}for(const flow of Object.values(flows))for(const step of flow.steps)if(!ids.has(step.from)||!ids.has(step.to))throw new Error('Unknown flow endpoint');for(const f of Object.values(failures))if(!ids.has(f.node)||!flows[f.flow]||f.blockedStep<0||f.blockedStep>=flows[f.flow].steps.length)throw new Error('Invalid failure target');return true;}
